config.script:
$windowHours = [int]{{start.param.eventHours}}
$recordLimit = [int]{{start.param.eventLimit}}
$errorLimit = [int]{{start.param.errorThreshold}}
$memoryFloor = [int]{{start.param.minimumFreeMemory}}
$diskFloor = [int]{{start.param.minimumFreeDisk}}
if ($windowHours -lt 1 -or $windowHours -gt 168) { throw 'eventHours must be 1-168.' }
if ($recordLimit -lt 1 -or $recordLimit -gt 500) { throw 'eventLimit must be 1-500 per log.' }
if ($errorLimit -lt 0 -or $errorLimit -gt 1001) { throw 'errorThreshold must be 0-1001.' }
if ($memoryFloor -lt 1 -or $memoryFloor -gt 99 -or $diskFloor -lt 1 -or $diskFloor -gt 99) { throw 'Free-space thresholds must be 1-99 percent.' }
$rootPath = Join-Path ([IO.Path]::GetTempPath()) ('NodePilot-SystemCheck-' + {{run-id.param.text}})
$sourcePath = Join-Path $rootPath 'Report'
$reportPath = Join-Path $sourcePath 'SystemReport.txt'
$jsonPath = Join-Path $sourcePath 'Findings.json'
$readmePath = Join-Path $sourcePath 'Readme.txt'
$archivePath = Join-Path $rootPath 'SystemCheck.zip'
$extractPath = Join-Path $rootPath 'Verification'
$systemDrive = $env:SystemDrive
Write-Output "Run directory: $rootPath"

$totalMemory = [double]{{os.param.TotalVisibleMemorySize}}
$availableMemory = [double]{{os.param.FreePhysicalMemory}}
if ($totalMemory -le 0) { throw 'Invalid total memory from WMI.' }
$memoryPercent = [math]::Round(100 * $availableMemory / $totalMemory, 2)
Write-Output "Available memory: $memoryPercent percent"

$diskSize = [double]{{disk.param.Size}}
$diskFree = [double]{{disk.param.FreeSpace}}
if ($diskSize -le 0) { throw 'Invalid disk size from WMI.' }
$diskPercent = [math]::Round(100 * $diskFree / $diskSize, 2)
$diskSummary = [ordered]@{freePercent=$diskPercent;freeGiB=[math]::Round($diskFree / 1GB,2);totalGiB=[math]::Round($diskSize / 1GB,2)}
$diskSummary | ConvertTo-Json -Compress

$eventWindow = [int]{{paths.param.windowHours}}
$eventCap = [int]{{paths.param.recordLimit}}
$eventItems = New-Object 'System.Collections.Generic.List[object]'
$eventTruncated = $false
foreach ($eventLogName in @('System','Application')) {
 $eventQueryText = "*[System[(Level=1 or Level=2) and TimeCreated[timediff(@SystemTime) <= $([long]$eventWindow * 3600000)]]]"
 $eventQuery = New-Object System.Diagnostics.Eventing.Reader.EventLogQuery($eventLogName,[System.Diagnostics.Eventing.Reader.PathType]::LogName,$eventQueryText)
 $eventQuery.ReverseDirection = $true
 $eventReader = New-Object System.Diagnostics.Eventing.Reader.EventLogReader($eventQuery)
 $eventSeen = 0
 try {
  while ($null -ne ($eventRecord = $eventReader.ReadEvent())) {
   try {
    if ($eventSeen -ge $eventCap) { $eventTruncated = $true; break }
    $eventItems.Add([pscustomobject]@{log=$eventLogName;provider=$eventRecord.ProviderName;id=$eventRecord.Id;level=$eventRecord.Level;timeUtc=$eventRecord.TimeCreated.ToUniversalTime().ToString('o')})
    $eventSeen++
   } finally { $eventRecord.Dispose() }
  }
 } finally { $eventReader.Dispose() }
}
$errorCount = @($eventItems | Where-Object level -eq 2).Count
$criticalCount = @($eventItems | Where-Object level -eq 1).Count
$eventGroups = @($eventItems | Group-Object log,provider,id | Sort-Object Count -Descending | Select-Object -First 5 | ForEach-Object { [pscustomobject]@{log=$_.Group[0].log;provider=$_.Group[0].provider;eventId=$_.Group[0].id;count=$_.Count;latestUtc=$_.Group[0].timeUtc} })
$summaryXml = "<eventReview criticalCount='$criticalCount' />"
$eventSummaryJson = ConvertTo-Json -InputObject ([ordered]@{errorCount=$errorCount;criticalCount=$criticalCount;truncated=$eventTruncated;hours=$eventWindow;limitPerLog=$eventCap;groups=$eventGroups}) -Depth 5 -Compress
# Only the bounded summary is needed by downstream activities.
$eventItems = $null
$eventRecord = $null
$eventQuery = $null
$eventReader = $null
Write-Output $eventSummaryJson

$findingsList = New-Object 'System.Collections.Generic.List[string]'
$assessedMemory = [double]{{memory.param.memoryPercent}}
$assessedDisk = [double]{{disk-value.param.result}}
$assessedErrors = [int]{{errors.param.result}}
$assessedCritical = [int]{{critical.param.result}}
if ($assessedMemory -lt [int]{{paths.param.memoryFloor}}) { $findingsList.Add('Free memory below configured threshold.') }
if ($assessedDisk -lt [int]{{paths.param.diskFloor}}) { $findingsList.Add('Free system disk space below configured threshold.') }
if ($assessedErrors -ge [int]{{paths.param.errorLimit}}) { $findingsList.Add('Error event count reached configured threshold.') }
if ($assessedCritical -gt 0) { $findingsList.Add('Critical events found in selected time window.') }
$serviceStates = [ordered]@{EventLog={{event-service.param.status}};RpcSs={{rpc-service.param.status}};WinRM={{winrm-service.param.status}};MpsSvc={{firewall.param.status}}}
foreach ($serviceEntry in $serviceStates.GetEnumerator()) { if ($serviceEntry.Value -ne 'Running') { $findingsList.Add("Service requires review: $($serviceEntry.Key) = $($serviceEntry.Value)") } }
$restartPending = ({{cbs-reboot.param.exists}} -eq 'True') -or ({{wu-reboot.param.exists}} -eq 'True')
if ($restartPending) { $findingsList.Add('A servicing or Windows Update restart flag is present.') }
$adapterCount = [int]{{network.param.count}}
if ($adapterCount -lt 1) { $findingsList.Add('No IP-enabled network adapter found.') }
if ({{events.param.eventTruncated}} -eq 'True') { $findingsList.Add('Event selection was limited; additional matching records exist.') }
$reviewCount = $findingsList.Count
$outcome = if ($reviewCount -gt 0) { 'Review' } else { 'Clear' }
$checkedAtUtc = [datetime]::UtcNow.ToString('o')
$assessedEvents = ConvertFrom-Json {{events.output}}
$findingsJson = ConvertTo-Json -InputObject ([ordered]@{computer={{os.param.CSName}};checkedAtUtc=$checkedAtUtc;outcome=$outcome;thresholds=[ordered]@{minimumFreeMemory=[int]{{paths.param.memoryFloor}};minimumFreeDisk=[int]{{paths.param.diskFloor}};errorThreshold=[int]{{paths.param.errorLimit}}};findings=$findingsList.ToArray();windows={{os.param.Caption}};version={{os.param.Version}};buildRevision={{build.param.value}};processor={{cpu.output}};freeMemoryPercent=$assessedMemory;freeSystemDiskPercent=$assessedDisk;services=$serviceStates;stoppedAutomaticServices=[int]{{auto-services.param.count}};restartPending=$restartPending;ipEnabledAdapters=$adapterCount;events=$assessedEvents}) -Depth 8 -Compress
$reportLines = @('SYSTEM CHECK',("Computer: " + {{os.param.CSName}}),"Checked at (UTC): $checkedAtUtc","Outcome: $outcome",'',"Free memory: $assessedMemory percent","Free system disk: $assessedDisk percent","IP-enabled adapters: $adapterCount","Restart flag: $restartPending","Errors: $assessedErrors | Critical: $assessedCritical",'', 'FINDINGS')
if ($reviewCount -eq 0) { $reportLines += 'No configured review condition matched.' } else { $reportLines += $findingsList.ToArray() }
$reportLines += @('', 'SCOPE', 'This is a local snapshot, not a root cause diagnosis.','Stopped automatic services are informational; trigger-start services may stop by design.','Restart flags cover servicing and Windows Update only. Firewall service status does not describe firewall rules.','Event counts refer to the selected window and per-log limit. See Findings.json for grouped events and details.')
$reportText = $reportLines -join "`r`n"
Write-Output "$outcome : $reviewCount review findings"

$originalFolder = {{paths.param.sourcePath}}
$restoredFolder = {{paths.param.extractPath}}
$checkedArchive = {{paths.param.archivePath}}
$files = @(Get-ChildItem -LiteralPath $restoredFolder -File -Recurse -ErrorAction Stop)
if ($files.Count -ne 3) { throw 'The archive must contain exactly three report files.' }
foreach ($name in @('SystemReport.txt', 'Findings.json', 'Readme.txt')) {
    $restored = @($files | Where-Object Name -eq $name)
    if ($restored.Count -ne 1) { throw "File missing from archive: $name" }
    $originalHash = (Get-FileHash -LiteralPath (Join-Path $originalFolder $name) -Algorithm SHA256 -ErrorAction Stop).Hash
    $restoredHash = (Get-FileHash -LiteralPath $restored[0].FullName -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($originalHash -ne $restoredHash) { throw "Archive content does not match: $name" }
}
$verified = $true
$archiveBytes = (Get-Item -LiteralPath $checkedArchive -ErrorAction Stop).Length
Write-Output "Archive verified: 3 files with matching contents, $archiveBytes Bytes."
